/* APEX service worker — installable game shell + offline world tiles.
 *
 * Install caches the app shell from assets/pwa/precache.json (generated by
 * tools/make-precache.mjs). World tiles, the current car texture and the CDN
 * copies of three.js/fonts are cached by stale-while-revalidate as they are
 * used, and the page also sends the URLs it loaded so an offline relaunch of a
 * visited world works.
 */
const VERSION = 'apex-v3';
const SHELL_CACHE = `apex-shell-${VERSION}`;
const RUNTIME_CACHE = `apex-runtime-${VERSION}`;
const RUNTIME_LIMIT = 1200;
const PRECACHE_URL = './assets/pwa/precache.json';

// Used when precache.json is missing (e.g. an older deployment).
const SHELL_FALLBACK = [
    './',
    './index.html',
    './manifest.webmanifest',
    './assets/pwa/icon-192.png',
    './assets/pwa/icon-512.png',
    './assets/pwa/icon-maskable-512.png',
    './assets/pwa/apple-touch-icon-180.png',
    './src/main.js',
    './src/pwa.js',
    './src/ui/TouchControls.js'
];

self.addEventListener('install', (event) => {
    event.waitUntil((async () => {
        const cache = await caches.open(SHELL_CACHE);
        const urls = new Set([...SHELL_FALLBACK, ...(await readPrecacheList())]);
        // addAll() is atomic; one 404 would abort the install, so add entries
        // individually and let optional ones fail quietly.
        await Promise.all([...urls].map((url) => cache.add(url).catch(() => null)));
        await self.skipWaiting();
    })());
});

self.addEventListener('activate', (event) => {
    event.waitUntil((async () => {
        const keep = new Set([SHELL_CACHE, RUNTIME_CACHE]);
        for (const key of await caches.keys()) {
            if (!keep.has(key)) await caches.delete(key);
        }
        await self.clients.claim();
    })());
});

self.addEventListener('message', (event) => {
    if (event.data === 'SKIP_WAITING') {
        self.skipWaiting();
        return;
    }
    // The page reports what it actually loaded so a later offline launch has
    // the world tiles, CDN modules and vehicle textures it needs.
    if (event.data && event.data.type === 'WARM' && Array.isArray(event.data.urls)) {
        event.waitUntil(warm(event.data.urls));
    }
});

self.addEventListener('fetch', (event) => {
    const request = event.request;
    if (request.method !== 'GET') return;

    let url;
    try { url = new URL(request.url); } catch { return; }

    if (!isCacheable(url)) return;

    if (request.mode === 'navigate') {
        event.respondWith(networkFirst(request));
        return;
    }

    event.respondWith(staleWhileRevalidate(request, event));
});

function isCacheable(url) {
    return url.origin === self.location.origin || isCdn(url);
}

function isCdn(url) {
    return url.hostname === 'cdn.jsdelivr.net' ||
        url.hostname === 'fonts.googleapis.com' ||
        url.hostname === 'fonts.gstatic.com';
}

async function readPrecacheList() {
    try {
        const response = await fetch(PRECACHE_URL, { cache: 'no-store' });
        if (!response.ok) return [];
        const list = await response.json();
        return Array.isArray(list) ? list : [];
    } catch {
        return [];
    }
}

/** Cache the URLs the page has already loaded (best effort). */
async function warm(urls) {
    const cache = await caches.open(RUNTIME_CACHE);
    const seen = new Set();
    for (const raw of urls) {
        if (typeof raw !== 'string' || seen.has(raw)) continue;
        seen.add(raw);
        let url;
        try { url = new URL(raw, self.location.origin); } catch { continue; }
        if (!isCacheable(url)) continue;
        if (await cache.match(url.href)) continue;
        try {
            const response = await fetch(url.href, { credentials: 'same-origin' });
            if (response && (response.ok || response.type === 'opaque')) {
                await cache.put(url.href, response);
            }
        } catch { /* not reachable right now */ }
    }
    await trim(cache);
}

async function networkFirst(request) {
    const cache = await caches.open(RUNTIME_CACHE);
    try {
        const response = await fetch(request);
        if (response && response.ok) cache.put(request, response.clone());
        return response;
    } catch {
        return (await cache.match(request)) ||
            (await caches.match('./index.html')) ||
            (await caches.match('./')) ||
            Response.error();
    }
}

async function staleWhileRevalidate(request, event) {
    const cache = await caches.open(RUNTIME_CACHE);
    const cached = await cache.match(request);

    const network = fetch(request).then((response) => {
        if (response && (response.ok || response.type === 'opaque')) {
            cache.put(request, response.clone()).then(() => trim(cache)).catch(() => null);
        }
        return response;
    }).catch(() => null);

    if (cached) {
        // Keep the copy fresh for the next launch; this frame uses cache.
        event.waitUntil(network);
        return cached;
    }

    const response = await network;
    if (response) return response;
    const fallback = await caches.match(request);
    if (fallback) return fallback;
    return Response.error();
}

let puts = 0;
async function trim(cache) {
    puts++;
    if (puts % 40 !== 0) return;
    const keys = await cache.keys();
    if (keys.length <= RUNTIME_LIMIT) return;
    const drop = keys.length - RUNTIME_LIMIT;
    for (let i = 0; i < drop; i++) await cache.delete(keys[i]);
}
